file.content:
/*
 * Key Value Pair lays out a label (key) and a value side by side in a horizontal row. The key takes
 * a fixed proportion of the row width; the value fills the rest. When children are provided (an
 * inline-editable control like TextField/TextArea/Select with context="inline"), they fill the
 * value slot. Static pairs render plain text in the value slot.
 */
.root {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-lg);
  min-block-size: var(--size-control-md);
}

.underline {
  border-bottom: var(--border-width-sm) solid var(--color-border-default);
}

.key {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  min-inline-size: 0;
  min-block-size: var(--size-control-md);
  inline-size: 40%;
  padding-inline-start: var(--spacing-sm);
  color: var(--color-content-subtle);
  font-family: var(--typography-body-md-font-family);
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-body-md-font-weight);
  line-height: var(--typography-body-md-line-height);
  letter-spacing: var(--typography-body-md-letter-spacing);
  margin: 0;
}

.value {
  flex: 1 1 auto;
  min-inline-size: 0;
  color: var(--color-content-default);
  font-family: var(--typography-body-md-font-family);
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-body-md-font-weight);
  line-height: var(--typography-body-md-line-height);
  letter-spacing: var(--typography-body-md-letter-spacing);
  margin: 0;
  padding: 0;
}

.value_static {
  align-self: center;
  padding-inline-start: var(--spacing-sm);

